const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cats=['Anti data center','Pro data center','Pro data center regulation','Anti data center regulation'];
const party=p=>p==='D'?'Democrat':p==='R'?'Republican':'Independent';
const chamberMembers=ch=>DATA.members.filter(p=>!ch||p.chamber===ch);
const seat=p=>p.chamber==='House'?p.district:'Senate';
const election=p=>p.electionSource||DATA.roster;
const allcats=[...cats,'No documented position'];
const tag=c=>`<span class="tag ${c==='No documented position'?'unknown':''}">${esc(c)}</span>`;
const memberLink=p=>`#profile/${p.id}`;
const sources=p=>p.sources.map(s=>`<li class="evidence"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a><br><span class="note">${esc(s.type||'Source')} · ${esc(s.date||'Date not stated')}</span>${s.summary?`<p>${esc(s.summary)}</p>`:''}${s.quote?`<blockquote>“${esc(s.quote)}”</blockquote><p class="note">${esc(s.attribution||p.name)}</p>`:''}${s.note?`<p class="note">${esc(s.note)}</p>`:''}</li>`).join('');
function intro(k,title,desc){return `<div class="hero"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="lede">${desc}</p></div><div class="snapshot">LAST RESEARCHED<br><strong>November 6, 2026</strong><br>Race calls, not certification</div></div>`}
function card(p){return `<article class="card ${p.party}"><div class="state">${esc(seat(p))} · ${esc(p.state)}${p.returning?' · Returning member':''}</div><h3><a href="${memberLink(p)}">${esc(p.name)} ↗</a></h3><div class="party ${p.party}"><span class="dot"></span>${party(p.party)} · ${esc(p.chamber)}</div><p>${esc(p.summary)}</p><div class="tags">${(p.categories.length?p.categories:['No documented position']).map(tag).join('')}</div><div class="bottom"><span>${p.sources.length} sources · ${esc(p.priorityLabel)}</span><a href="${memberLink(p)}">View profile →</a></div></article>`}
function count(c,part,arr=DATA.members){return arr.filter(p=>(c==='No documented position'?!p.categories.length:p.categories.includes(c))&&(!part||p.party===part)).length}
function bars(arr=DATA.members){return allcats.map(c=>`<div class="barrow"><div class="barhead"><span>${c}</span><strong>${count(c,null,arr)} / ${arr.length}</strong></div><div class="track" role="img" aria-label="${c}: ${count(c,'D',arr)} Democrats, ${count(c,'R',arr)} Republicans, out of ${arr.length} profiles"><span class="seg D" style="width:${100*count(c,'D',arr)/Math.max(1,arr.length)}%"></span><span class="seg R" style="width:${100*count(c,'R',arr)/Math.max(1,arr.length)}%"></span></div></div>`).join('')}
const legend=`<div class="legend"><span><i class="dot D"></i>Democrats</span><span><i class="dot R"></i>Republicans</span></div>`;
function evidenceChart(){let labels=['Official platform','Campaign statements','Congressional record','State/local record','No position located'];return `<section class="panel" style="margin-top:24px"><div class="eyebrow">CAMPAIGN VISIBILITY</div><h2>What kind of evidence supports each profile?</h2>${legend}${labels.map(label=>{let a=DATA.members.filter(p=>p.priorityLabel===label);return `<div class="barrow"><div class="barhead"><span>${label}</span><strong>${a.length} / ${DATA.members.length}</strong></div><div class="track" role="img" aria-label="${label}: ${a.length} profiles"><span class="seg D" style="width:${100*a.filter(p=>p.party==='D').length/DATA.members.length}%"></span><span class="seg R" style="width:${100*a.filter(p=>p.party==='R').length/DATA.members.length}%"></span></div></div>`}).join('')}<p class="note">One evidence label per profile. A congressional vote establishes an action, but does not establish that data centers were a campaign priority. Official platforms may also have interview or voting evidence.</p></section>`}
function voteChart(){let v=DATA.baseline.find(x=>x.id==='ratepayer').votes;return `<section class="panel" style="margin-top:24px"><div class="eyebrow">H.R. 9340 / RECORDED VOTES</div><h2>How each party voted</h2><div class="grid">${['house','senate'].map(ch=>`<div><h3>${ch==='house'?'House passage':'Senate cloture'} · ${v[ch].date}</h3>${['Democratic','Republican','Independent'].map(part=>{let a=v[ch][part],total=a.yea+a.nay+(a.notVoting||0),color=part==='Democratic'?'#2463c4':part==='Republican'?'#bb423c':'#64716c';return `<div class="barrow"><div class="barhead"><span>${part}</span><span>${a.yea} yea · ${a.nay} nay${a.notVoting?' · '+a.notVoting+' not voting':''}</span></div><div class="track" role="img" aria-label="${part}: ${a.yea} yea, ${a.nay} nay, ${a.notVoting||0} not voting"><span style="width:${a.yea/total*100}%;background:${color}"></span><span style="width:${a.nay/total*100}%;background:repeating-linear-gradient(45deg,${color},${color} 2px,white 2px,white 5px)"></span></div></div>`}).join('')}<a href="${DATA.voteSources[ch]}" target="_blank" rel="noopener">Official ${ch} roll call ↗</a></div>`).join('')}</div><p class="note">Solid = yea; striped = nay; gray = not voting. Each bar’s denominator is that party’s membership recorded in the roll call. Senate cloture is a procedural vote, not final passage. These votes are not coded as a simple pro/anti-regulation score.</p></section>`}


function currentSummary(){const b=DATA.baseline;return `<section style="margin-top:36px"><div class="sectiontop"><div><div class="eyebrow">CURRENT CONGRESS / 119TH · 2025–2026</div><h2>What has Congress done about data centers?</h2></div><a class="button primary" href="#congress">Explore the congressional record →</a></div><p>Track legislation, recorded votes, hearings and oversight alongside incoming members’ promises.</p><div class="stats">${[[b.length,'Selected action records'],[b.filter(x=>x.status==='Enacted').length,'Enacted provision'],[b.filter(x=>x.status==='Introduced / referred').length,'Introduced proposal records'],[b.filter(x=>x.status==='Passed House / Senate cloture failed').length,'House-passed bill stalled in Senate']].map(([n,label])=>`<div class="stat"><div class="number">${n}</div><p>${label}</p></div>`).join('')}</div><div class="grid"><article class="panel"><h3>Already law: military resource planning</h3><p>The defense authorization law requires planning for electricity, water and community effects of military data centers. Its scope is military installations, not all commercial facilities.</p><a target="_blank" rel="noopener" href="${esc(b.find(x=>x.id==='ndaa1531').sources[0].url)}">Read the enacted provision · §1531 ↗</a></article><article class="panel"><h3>A major vote: ratepayer protection</h3><p>H.R. 9340 passed the House 417–3. Senate cloture failed 57–43. The proposal has not become law in this reviewed record.</p><a href="#congress">See votes by party and the bill’s limits →</a></article></div><p class="note">Selected records through November 6, 2026, not a census of all congressional activity. Five proposal records group six bills, including the paired moratorium bills. One hearing and one oversight report are also included. Counts describe records, not lawmakers or support levels.</p></section>`}
function actionCharts(){const b=DATA.baseline;const status=[...new Set(b.map(x=>x.status))];const themes=[...new Set(b.flatMap(x=>x.themes))].sort((a,c)=>b.filter(x=>x.themes.includes(c)).length-b.filter(x=>x.themes.includes(a)).length);const chart=(labels,test)=>labels.map(label=>{const n=b.filter(x=>test(x,label)).length;return `<div class="barrow"><div class="barhead"><span>${esc(label)}</span><strong>${n} / ${b.length}</strong></div><div class="track" role="img" aria-label="${esc(label)}: ${n} of ${b.length} selected records"><span style="width:${100*n/b.length}%;background:#16766e"></span></div></div>`}).join('');return `<div class="grid" style="margin:24px 0"><section class="panel"><h2>How far have actions progressed?</h2>${chart(status,(x,l)=>x.status===l)}<p class="note">One status per record. A hearing or oversight report does not enact legislation.</p></section><section class="panel"><h2>Which issues appear in the record?</h2>${chart(themes,(x,l)=>x.themes.includes(l))}<p class="note">Topics overlap. Counts measure coverage in these ${b.length} selected records, not the full congressional agenda.</p></section></div>`}

function overview(){const m=DATA.members,house=chamberMembers('House'),senate=chamberMembers('Senate'),classified=m.filter(p=>p.categories.length).length;$('#main').innerHTML=intro('HOUSE + SENATE / THE INCOMING 120TH CONGRESS','The incoming congress and data centers','Explore what incoming representatives and senators have said, promised and voted on. Follow the evidence on energy, water, development and local control.')+`<div class="stats"><div class="stat"><div class="number">${house.length}</div><p>New & returning House members</p></div><div class="stat"><div class="number">${senate.length}</div><p>New & returning senators</p></div><div class="stat"><div class="number">${classified}<small> / ${m.length}</small></div><p>Profiles with a documented position</p></div><div class="stat"><div class="number">${m.length-classified}</div><p>No position located in reviewed sources</p></div></div><div class="sectiontop"><h2>Comparing new members of the House and Senate</h2><div><a class="button primary" href="#directory?chamber=House">Explore the House →</a> <a class="button" href="#directory?chamber=Senate">Explore the Senate →</a></div></div><div class="grid chambercharts">${[['House',house],['Senate',senate]].map(([ch,arr])=>`<section class="panel"><div class="eyebrow">${ch==='House'?'INCOMING REPRESENTATIVES':'INCOMING SENATORS'}</div><h2>${ch} · ${arr.length} profiles</h2>${legend}${bars(arr)}<p class="note">Denominator: ${arr.length} ${ch.toLowerCase()} profiles. Position labels overlap. No documented position is a research status, not neutrality.</p><details><summary>View ${ch.toLowerCase()} chart data</summary>${chartTable(arr)}</details></section>`).join('')}</div><div class="callout"><strong>Read beyond the label.</strong> Support for construction can coexist with support for regulation. The “Anti data center” category includes temporary moratoria, with scope and duration explained on each profile. Missing evidence is never interpreted as a position.</div>${evidenceChart()}${currentSummary()}<div class="sectiontop"><h2>Explore the source trail</h2><a href="#directory">All ${m.length} profiles →</a></div><div class="cards">${[...house.filter(p=>p.categories.length).slice(0,2),senate.find(p=>p.id==='abdul-el-sayed')].filter(Boolean).map(card).join('')}</div><div class="callout"><strong>Coverage note.</strong> ${esc(DATA.coverageNote||'Called winners only; incumbents winning reelection are excluded.')} ${esc(DATA.timing)} <a href="#methodology">See roster, exclusions and research limits.</a></div>`}
function chartTable(arr){return `<div class="tablewrap"><table><caption class="note">Overlapping position counts</caption><thead><tr><th>Position</th><th>Democrats</th><th>Republicans</th><th>Total</th></tr></thead><tbody>${allcats.map(c=>`<tr><td>${c}</td><td>${count(c,'D',arr)}</td><td>${count(c,'R',arr)}</td><td>${count(c,null,arr)}</td></tr>`).join('')}</tbody></table></div>`}
let filters={q:'',chamber:'',party:'',cat:'',state:'',priority:''};
function directory(){let states=[...new Set(DATA.members.map(p=>p.state))].sort();$('#main').innerHTML=intro('THE RESEARCH DIRECTORY','Find a member. Follow the evidence.','Search names, districts, states, proposals, quotations and source notes. Choose a chamber, party or overlapping policy position.')+`<div class="filters"><label>Search the evidence<input id="query" type="search" placeholder="Try electricity, water or moratorium" value="${esc(filters.q)}"></label><label>Chamber<select id="chamber"><option value="">House & Senate</option><option>House</option><option>Senate</option></select></label><label>Party<select id="party"><option value="">All parties</option><option value="D">Democrats</option><option value="R">Republicans</option></select></label><label>Position<select id="category"><option value="">All positions</option>${[...cats,'No documented position'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>State<select id="state"><option value="">All states</option>${states.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Campaign evidence<select id="priority"><option value="">All evidence</option><option>Official platform</option><option>Campaign statements</option><option>Congressional record</option><option>State/local record</option><option>No position located</option></select></label></div><div class="sectiontop"><span id="resultcount" role="status" aria-live="polite"></span><div><button id="reset">Clear filters</button> <button id="export">Export filtered CSV ↓</button></div></div><div id="results"></div><details class="panel" style="margin-top:25px"><summary>Position counts for this selection</summary><div id="filteredchart"></div></details>`;$('#chamber').value=filters.chamber;$('#party').value=filters.party;$('#category').value=filters.cat;$('#state').value=filters.state;$('#priority').value=filters.priority;for(let [id,key] of [['query','q'],['chamber','chamber'],['party','party'],['category','cat'],['state','state'],['priority','priority']])$('#'+id).addEventListener(id==='query'?'input':'change',e=>{filters[key]=e.target.value;results()});$('#reset').onclick=()=>{filters={q:'',chamber:'',party:'',cat:'',state:'',priority:''};directory()};$('#export').onclick=()=>exportCSV(filtered());results()}
function filtered(){return DATA.members.filter(p=>(!filters.chamber||p.chamber===filters.chamber)&&(!filters.party||p.party===filters.party)&&(!filters.state||p.state===filters.state)&&(!filters.priority||p.priorityLabel===filters.priority)&&(!filters.cat||(filters.cat==='No documented position'?!p.categories.length:p.categories.includes(filters.cat)))&&(!filters.q||JSON.stringify(p).toLowerCase().includes(filters.q.toLowerCase())))}
function results(){let m=filtered();$('#resultcount').textContent=`${m.length} of ${DATA.members.length} profiles · grouped by political party`;$('#results').innerHTML=m.length?['D','R'].map(part=>{let a=m.filter(p=>p.party===part);return a.length?`<h2 class="party ${part}" style="margin:25px 0 15px"><span class="dot"></span>${part==='D'?'Democrats':'Republicans'} · ${a.length}</h2><div class="cards">${a.map(card).join('')}</div>`:''}).join(''):`<div class="panel empty">No profiles match these filters. Try a broader term or clear your filters.</div>`;$('#filteredchart').innerHTML=legend+bars(m)+chartTable(m)}
function profile(id){const p=DATA.members.find(p=>p.id===id);if(!p){$('#main').innerHTML='<h1>Profile not found</h1><a href="#directory">Return to directory</a>';return}$('#main').innerHTML=`<a href="#directory">← Member directory</a>`+intro(`${esc(p.state.toUpperCase())} / ${esc(seat(p))} / ${p.returning?'RETURNING MEMBER':p.chamber==='House'?'REPRESENTATIVE-ELECT':'SENATOR-ELECT'}`,esc(p.name),esc(p.summary))+`<div class="sectiontop"><div class="party ${p.party}"><span class="dot"></span>${party(p.party)} · Election called · ${esc(p.electionDate||'November 2026')}</div><button onclick="window.print()">Print profile</button></div><div class="tags" style="margin-bottom:25px">${(p.categories.length?p.categories:['No documented position']).map(tag).join('')}</div><div class="profilegrid"><div><section class="panel"><div class="eyebrow">POLICY & CAMPAIGN</div><h2>Positions & policy proposals</h2>${p.proposals.length?`<ul>${p.proposals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>No specific data-center proposal was located in the sources reviewed. This does not establish support, opposition or neutrality.</p>'}<h3>Was it a campaign priority?</h3><p>${esc(p.campaignPriority)}</p>${p.quote?`<blockquote>“${esc(p.quote)}”</blockquote><p class="note">${esc(p.quoteAttribution)}</p>`:''}<div class="callout"><strong>Classification rationale</strong><br>${esc(p.classificationNote)}</div>${p.timingNote?`<p class="note">${esc(p.timingNote)}</p>`:''}</section><section class="panel" style="margin-top:24px"><div class="eyebrow">SOURCE TRAIL</div><h2>Evidence & further reading</h2><ol>${sources(p)}</ol><p class="note">All sources researched November 6, 2026. Dates above are publication dates when available. Campaign claims are attributed, not independently endorsed.</p></section></div><aside><section class="panel"><h3>At a glance</h3><p><span class="muted">State</span><br>${esc(p.state)} · ${esc(seat(p))}</p><p><span class="muted">Evidence type</span><br>${esc(p.priorityLabel)}</p><p><span class="muted">Election status</span><br>Called by the linked election source; certification not asserted</p><p><span class="muted">Roster source</span><br><a target="_blank" rel="noopener" href="${esc(election(p).url)}">${esc(election(p).title)}</a></p><a href="#methodology">Read coding rules →</a></section><section class="panel" style="margin-top:20px"><h3>Research notes</h3><p class="note">${esc(p.researchNote||'A campaign statement is not a congressional vote. Review linked material and its scope before using a classification in reporting.')}</p><p class="note">Advertisements are recorded only when the ad or reliable reporting about it was located. No ad located does not mean no ad ran.</p></section></aside></div>`}
function congress(){const b=DATA.baseline;$('#main').innerHTML=intro('THE COMPARISON / 119TH CONGRESS','The current Congress and data centers','Compare the incoming class’s stated positions with selected, documented actions from the current Congress. Bills, votes and oversight are labeled separately.')+currentSummary()+actionCharts()+`<div class="callout"><strong>Different measures.</strong> Incoming-class charts count people and overlapping policy positions. The record below counts selected actions. It is not a roll-call scorecard for every current member and does not establish a before/after percentage change.</div><div class="grid"><section class="panel"><h2>Incoming House & Senate signals</h2>${legend}${bars()}<p class="note">${DATA.members.length} incoming or returning profiles. A label does not predict a future vote.</p></section><section class="panel"><div class="eyebrow">A KEY TEST: H.R. 9340</div><h2>House passage ≠ enacted law</h2><div class="number">417–3</div><p>House passage, September 16, 2026.</p><div class="number">57–43</div><p>Senate cloture vote, September 30, 2026. Cloture failed.</p><p class="note">The proposal asks state regulators to consider a cost-allocation standard. It does not itself require every regulator to adopt it. Opposition to this bill does not, by itself, establish opposition to regulation.</p><a href="${esc(DATA.voteSources.house)}" target="_blank" rel="noopener">House roll call ↗</a> · <a href="${esc(DATA.voteSources.senate)}" target="_blank" rel="noopener">Senate roll call ↗</a></section></div>${voteChart()}<div class="sectiontop"><h2>Selected federal actions</h2><button id="baselineExport">Export action data ↓</button></div><label for="actionsearch" class="note">Search actions, bill numbers and summaries</label><input id="actionsearch" type="search" placeholder="Search the congressional record" style="margin:6px 0 18px"><label for="actionstatus" class="note">Filter by legislative status</label><select id="actionstatus" style="margin:6px 0 18px"><option value="">All statuses</option>${[...new Set(b.map(x=>x.status))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><p id="actioncount" class="note" aria-live="polite"></p><div class="panel" id="actions"></div><div class="callout">State laws, utility commission decisions and White House executive orders are outside this congressional action count. State-level promises remain visible on candidate profiles with their jurisdiction identified.</div>`;const render=()=>{let q=$('#actionsearch').value.toLowerCase();let items=b.filter(x=>JSON.stringify(x).toLowerCase().includes(q)&&(!$('#actionstatus').value||x.status===$('#actionstatus').value));$('#actioncount').textContent=items.length+' of '+b.length+' selected action records';$('#actions').innerHTML=items.length?items.map(x=>`<article class="baseline"><div><div class="eyebrow">${esc(x.date)}</div><p class="status">${esc(x.status)}</p></div><div><h3>${esc(x.title)}</h3><div class="note">${esc(x.bill||'')} · ${esc(x.actor||'')}</div><p>${esc(x.summary)}</p>${x.caveat?`<p class="note">${esc(x.caveat)}</p>`:''}<ul class="tiny">${x.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a></li>`).join('')}</ul></div></article>`).join(''):'<p>No matching actions.</p>'};$('#actionsearch').oninput=render;$('#actionstatus').onchange=render;$('#baselineExport').onclick=()=>download('congress-actions-2026-11-06.json',JSON.stringify(b,null,2),'application/json');render()}
function methodology(){$('#main').innerHTML=intro('TRANSPARENCY / HOW TO USE THIS DATA','An evidence trail, not a prediction.','The unit of analysis is a member and a documented position. The dashboard preserves policy scope, uncertainty and links to the underlying material.')+`<div class="profilegrid"><div><section class="panel"><h2>Scope & roster</h2><p>This edition covers ${chamberMembers('House').length} new or returning House members and ${chamberMembers('Senate').length} new or returning senators with documented election calls. It excludes serving members winning reelection, including members already seated through special elections. Returning former members are marked. Nonvoting delegates are excluded from the voting-member totals. ${esc(DATA.coverageNote||'')}</p><p>${esc(DATA.timing)}</p><p>Senate roster: <a target="_blank" rel="noopener" href="${DATA.roster.url}">${esc(DATA.roster.title)}</a>, November 5, 2026. Calls are not certification. This is a November 6 research snapshot, not an automatically updating results feed.</p><p>House roster: each House profile links to its election-call source. Cross-checked against <a href="https://www.artba.org/election-brief/" target="_blank" rel="noopener">ARTBA’s newcomer list</a> and <a href="https://ballotpedia.org/Election_results,_2026:_U.S._House" target="_blank" rel="noopener">Ballotpedia’s results</a>. Lists are starting points; individual source verification governs inclusion.</p><h3>Pending races & roster exclusions</h3><p>${esc(DATA.housePendingNote||'House calls continue; an uncalled candidate is not counted as a winner.')}</p><ul>${DATA.pending.map(p=>`<li><strong>${esc(p.state)}</strong>: ${esc(p.description)} <a href="${esc(p.url)}" target="_blank" rel="noopener">Source ↗</a></li>`).join('')}</ul></section><section class="panel" style="margin-top:24px"><h2>Classification rules</h2><div class="tablewrap"><table><thead><tr><th>Label</th><th>What qualifies</th></tr></thead><tbody><tr><td>Anti data center</td><td>Explicit opposition to construction, including a proposed moratorium. The profile states geography and duration. This does not always mean a permanent nationwide ban.</td></tr><tr><td>Pro data center</td><td>Affirmative support for development or expansion. Recognizing possible benefits alone is insufficient.</td></tr><tr><td>Pro data center regulation</td><td>Specific support for binding safeguards, regulatory review, cost allocation, disclosure, environmental protections or local decision-making requirements. A vote to require consideration of a standard is marked as that limited action.</td></tr><tr><td>Anti data center regulation</td><td>Specific opposition to data-center safeguards or support for removing them. General support for AI, energy or deregulation is insufficient.</td></tr><tr><td>No documented position</td><td>No qualifying evidence located in the reviewed material. This is a research status, not a political position.</td></tr></tbody></table></div><p>Categories are nonexclusive. Coding is editorial interpretation grounded in the cited evidence, not a self-description by the candidate. Profiles explain the rationale and any limits.</p></section><section class="panel" style="margin-top:24px"><h2>Research protocol & limits</h2><ol><li>Verify each winner against a dated election call. Cross-check newcomer status and district; distinguish returning former members from sitting incumbents.</li><li>Search each candidate’s name with “data centers,” “data centres,” “moratorium,” “regulation” and campaign-related terms.</li><li>Review official campaign issue pages, congressional releases, legislative records, local news, interviews, debate transcripts and available ad reporting.</li><li>Separate official platform evidence, campaign remarks and an existing congressional record. A vote alone does not establish campaign priority.</li><li>Preserve source dates, short quotations, source notes and jurisdiction. Do not infer positions from party, donors or general AI policy.</li></ol><p>Search coverage is not exhaustive. Deleted pages, unindexed ads, inaccessible video and paywalls may leave gaps. Machine-generated or third-party transcripts are flagged and should be checked against original audio before publication. Candidates were not contacted for confirmation.</p><p>The congressional timeline is a selected baseline, not an exhaustive legislative inventory. “Introduced” and “passed House” do not mean enacted. Legislative statuses are limited to the dated evidence cited.</p></section></div><aside><section class="panel"><h3>Take the research with you</h3><p class="note">CSV contains member-level fields and source URLs. JSON preserves the full source trail, proposals, coding rationale and federal-action records.</p><button id="allcsv">Download all profiles · CSV</button><br><br><button id="alljson">Download full dataset · JSON</button><p class="note">Version 2 · 2026-11-06<br>Updates are manual in this edition.</p></section><section class="panel" style="margin-top:20px"><h3>Campaign evidence labels</h3><p><strong>Official platform</strong><br><span class="note">A specific commitment appears on an official campaign policy page.</span></p><p><strong>Campaign statements</strong><br><span class="note">Interviews, debates, campaign releases or documented ads establish a position.</span></p><p><strong>Congressional record</strong><br><span class="note">A federal vote or official action supports coding; a campaign priority may not be established.</span></p><p><strong>State/local record</strong><br><span class="note">A documented action in state or local office supports the classification.</span></p><p><strong>No position located</strong><br><span class="note">Targeted research did not locate qualifying evidence. This does not imply neutrality.</span></p></section></aside></div>`;$('#allcsv').onclick=()=>exportCSV(DATA.members);$('#alljson').onclick=()=>download('congress-data-center-watch-2026-11-06.json',JSON.stringify(DATA,null,2),'application/json')}
function download(name,data,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportCSV(arr){const rows=[['Name','Chamber','District','State','Party','Categories','Campaign evidence','Summary','Proposals','Quote','Attribution','Classification rationale','Source URLs','Election source','Research date'],...arr.map(p=>[p.name,p.chamber,p.district||'',p.state,party(p.party),p.categories.join('; '),p.campaignPriority,p.summary,p.proposals.join('; '),p.sources.filter(s=>s.quote).map(s=>s.quote).join('; '),p.sources.filter(s=>s.quote).map(s=>s.attribution||p.name).join('; '),p.classificationNote,p.sources.map(s=>s.url).join('; '),election(p).url,'2026-11-06'])];download('congress-member-profiles-2026-11-06.csv','\ufeff'+rows.map(r=>r.map(c=>'"'+String(c??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function route(){let [hash,query='']=(location.hash.slice(1)||'overview').split('?');let params=new URLSearchParams(query);if(hash==='directory'&&params.has('chamber')){filters.chamber=params.get('chamber');filters.q='';filters.party='';filters.cat='';filters.state='';filters.priority=''};document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(hash.startsWith('profile/')?'directory':hash)));if(hash.startsWith('profile/'))profile(hash.split('/')[1]);else ({overview,directory,congress,methodology}[hash]||overview)();document.title=(hash.startsWith('profile/')?(DATA.members.find(p=>p.id===hash.split('/')[1])?.name||'Profile')+' | ':'')+'Congress / Data Center Watch';window.scrollTo(0,0)}window.addEventListener('hashchange',route);route();
